            let mut f = x;
            let mask = x.rotate_left(17);
            for i in 0..8 { let m = (mask >> (i*3)) & 3; if m == 0 { f = (f & !(0xFFu64 << (8*i))) | (0x80u64 << (8*i)); } else if m == 1 { f &= !(0xFFu64 << (8*i)); } }
